//! The built-in stools' ControlPanels and `TOOL.Information` rows, transcribed from the game's
//! `gamemodes/sandbox/entities/weapons/gmod_tool/stools/*.lua` (`TOOL.BuildCPanel`, `TOOL.ClientConVar`,
//! `TOOL.Information`) and the `list.Set` tables they read (models, materials, effects, sounds).
//! Generated by a one-off script over the game files; data only. Open: the finger poser's
//! per-model finger bone sliders;
//! the eye poser's 2-axis `DSlider` is two sliders here and paint's `DListView` a choice.

/// One control of a tool's ControlPanel, in panel order. `label` strings are localisation keys
/// (`#tool.<mode>.<setting>`); `cmd` is the client convar the control writes.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Row {
    /// `CPanel:Help` / `ControlHelp`: a wrapped line of help text.
    Help(&'static str),
    /// `CPanel:Button(label, cmd)`: runs the console command.
    Button {
        label: &'static str,
        cmd: &'static str,
    },
    /// `CPanel:NumSlider(label, cmd, min, max, decimals)`.
    Slider {
        label: &'static str,
        cmd: &'static str,
        min: f32,
        max: f32,
        decimals: u8,
    },
    /// `CPanel:CheckBox(label, cmd)`.
    Check {
        label: &'static str,
        cmd: &'static str,
    },
    /// One binder of `CPanel:KeyBinder` (a two-key binder is two rows): a numpad key.
    Key {
        label: &'static str,
        cmd: &'static str,
    },
    /// `CPanel:ColorPicker(label, r, g, b)`.
    Color {
        label: &'static str,
        r: &'static str,
        g: &'static str,
        b: &'static str,
    },
    /// `ComboBoxMulti` / `PropSelect` / `MatSelect` / `RopeSelect`: one of `options` (label, value).
    Choice {
        label: &'static str,
        cmd: &'static str,
        options: &'static [(&'static str, &'static str)],
    },
    /// `CPanel:TextEntry(label, cmd)`.
    Text {
        label: &'static str,
        cmd: &'static str,
    },
}

/// A tool's panel, HUD information rows (`name`, stage or -1, operation or -1) and convar defaults.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Panel {
    pub tool: &'static str,
    pub rows: &'static [Row],
    pub info: &'static [(&'static str, i8, i8)],
    pub defaults: &'static [(&'static str, &'static str)],
}

/// The panel of a built-in tool.
pub fn panel(tool: &str) -> Option<&'static Panel> {
    PANELS.iter().find(|p| p.tool == tool)
}

